      SUBROUTINE BEAM3CC     THIRD-ORDER CONTRIBUTIONS TO BEAM MATRIXCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'UC2.CIN'      INCLUDE 'US.CIN'CC     LOCAL VARIABLESC      REAL  UST(5,6,21), USS(5,36,6), USSS(5,216), USSC(5,6)CC--------------------------------------------------------------C     THIRD-ORDER CONTRIBUTIONSC     PRODUCT OF RC2 AND SIC      DO 20 J = 1, 6      DO 20 K = 1, 6      SS = 0.0      DO 10 L1 = 1, 6      SS = SS + RC2(J,L1)*SI(L1,K)   10 CONTINUE      RS(J,K) = SS   20 CONTINUECC     PRODUCT OF UC2 AND SI DOUBLY CONTRACTEDC      DO 40 J = 1, 5      I234 = 0      DO 40 I4 = 1, 6      SS = 0.0      DO 30 I3 = 1, I4      DO 30 I2 = 1, I3      I234 = I234 + 1      SS = SS + UC2(J,I234)*SI(I2,I3)   30 CONTINUE      US(J,I4) = SS   40 CONTINUEC      DO 60 J = 1, 5      I234 = 0      DO 60 I4 = 1, 6      DO 60 I3 = 1, I4      DO 60 I2 = 1, I3      I234 = I234 + 1      US(J,I3) = US(J,I3) + UC2(J,I234)*SI(I2,I4)   60 CONTINUEC      DO 80 J = 1, 5      I234 = 0      DO 80 I4 = 1, 6      DO 80 I3 = 1, I4      DO 80 I2 = 1, I3      I234 = I234 + 1      US(J,I2)  = US(J,I2) + UC2(J,I234)*SI(I3,I4)   80 CONTINUECC     MULTIPLY U X SI TO GET MATRIX PRODUCT USC      DO 120 I1 = 1, 5      DO 105 I2 = 1, 6      DO 105 I34 = 1, 21      UST(I1,I2,I34) = 0.0  105 CONTINUEC      I234 = 0      I34 = 0      DO 120 I4 = 1, 6      DO 120 I3 = 1, I4      I34 = I34 + 1      DO 120 I2 = 1, I3      I234 = I234 + 1C      UFAC = UC2(I1,I234)      IF (UFAC .NE. 0.0) THEN        DO 110 I5 = 1, 6        UST(I1,I5,I34) = UST(I1,I5,I34) + UFAC*SI(I2,I5)  110   CONTINUE      ENDIF  120 CONTINUECC     MULTIPLY US X SI TO GET DOUBLE MATRIX PRODUCT USSC      DO 150 I1 = 1, 5      DO 130 I23 = 1, 36      DO 130 I4 = 1, 6      USS(I1,I23,I4) = 0.0  130 CONTINUEC      I34 = 0      DO 140 I4 = 1, 6      DO 140 I3 = 1, I4      I34 = I34 + 1      DO 140 I2 = 1, 6C      UFAC = UST(I1,I2,I34)      IF (UFAC .NE. 0.0) THEN        DO 135 I6 = 1, 6        I26 = I2 + 6*I6 - 6        USS(I1,I26,I4) = USS(I1,I26,I4) + UFAC*SI(I3,I6)  135   CONTINUE      ENDIF  140 CONTINUE  150 CONTINUECC     MULTIPLY USS X SI TO GET USSSC      DO 190 I1 = 1, 5      DO 170 I234 = 1, 216      USSS(I1,I234) = 0.0  170 CONTINUEC      DO 190 I4 = 1, 6      I23 = 0      DO 190 I3 = 1, 6      DO 190 I2 = 1, 6      I23 = I23 + 1C      UFAC = USS(I1,I23,I4)      IF (UFAC .NE. 0.0) THEN        DO 180 I7 = 1, 6        I237 = I2 + 6*I3 + 36*I7 - 42        USSS(I1,I237) = USSS(I1,I237) + UFAC*SI(I4,I7)  180   CONTINUE      ENDIF  190 CONTINUECC     CROSS PRODUCT BETWEEN FIRST AND THIRD ORDERC      DO 220 J = 1, 6      DO 220 K = 1, J      RSSU = 0.0      USSR = 0.0C      IF (K .LT. 5) THEN        DO 200 L1 = 1, 6        RSSU = RSSU + RS(J,L1)*US(K,L1)   200   CONTINUE      ENDIFC      IF (J .LT. 5) THEN        DO 210 L1 = 1, 6        USSR = USSR + US(J,L1)*RS(K,L1)  210   CONTINUE      ENDIFC      SIT(J,K) = SIT(J,K) + RSSU + USSR  220 CONTINUECC     MATRIX PRODUCT OF US AND SIC      DO 240 J = 1, 5      DO 240 K = 1, 6      SS = 0.0      DO 230 L1 = 1, 6      SS = SS + US(J,L1)*SI(L1,K)  230 CONTINUE      USSC(J,K) = SS  240 CONTINUECC     MATRIX PRODUCT OF US TIMES SI AND USC      DO 260 J = 1, 4      DO 260 K = 1, J      SS = 0.0      DO 250 L1 = 1, 6      SS = SS + USSC(J,L1)*US(K,L1)  250 CONTINUE      SIT(J,K) = SIT(J,K) + SS  260 CONTINUECC     PRODUCT OF USSS AND UC2C      DO 300 J = 1, 4      DO 300 K = 1, J      I234 = 0      SS = 0.0      DO 280 I4 = 1, 6      DO 280 I3 = 1, I4      DO 280 I2 = 1, I3      I234 = I234 + 1      IND = I2 + 6*I3 + 36*I4 - 42      SUM = USSS(J,IND)      IND = I2 + 6*I4 + 36*I3 - 42      SUM = SUM + USSS(J,IND)      IND = I3 + 6*I2 + 36*I4 - 42      SUM = SUM + USSS(J,IND)      IND = I3 + 6*I4 + 36*I2 - 42      SUM = SUM + USSS(J,IND)      IND = I4 + 6*I2 + 36*I3 - 42      SUM = SUM + USSS(J,IND)      IND = I4 + 6*I3 + 36*I2 - 42      SUM = SUM + USSS(J,IND)      SS = SS + SUM*UC2(K,I234)   280 CONTINUE      SIT(J,K) = SIT(J,K) + SS  300 CONTINUEC      RETURN      END